using Rhino; using Rhino.DocObjects; using Rhino.Geometry;
namespace RhinoContextAssist;
internal static class SelectionAnalyzer {
 public static SelectionContext Analyze(RhinoDoc doc){var s=doc.Objects.GetSelectedObjects(false,false).ToList();if(s.Count==0)s=doc.Objects.Where(o=>o.GetSelectedSubObjects()?.Length>0).ToList();if(s.Count==0)return new(SelectionKind.None,0,"Keine Auswahl",Point3d.Unset);var a=Box(s).Center;if(s.Count==1){var o=s[0];var sub=o.GetSelectedSubObjects();if(sub is{Length:>0})return Sub(o,sub[0],a);return Obj(o,a);}var ks=s.Select(o=>Obj(o,a).Kind).Distinct().ToList();return ks.Count==1?new(SelectionKind.Multiple,s.Count,$"{s.Count} Objekte",a):new(SelectionKind.Mixed,s.Count,$"{s.Count} gemischte Objekte",a);}
 static SelectionContext Sub(RhinoObject o,ComponentIndex ci,Point3d a){var n=ci.ComponentIndexType.ToString();var b=o.Geometry switch{Brep x=>x,Extrusion e=>e.ToBrep(),_=>null};if(n=="BrepFace"&&b!=null&&ci.Index>=0&&ci.Index<b.Faces.Count){var f=b.Faces[ci.Index];var p=f.GetBoundingBox(true).Center;return f.TryGetPlane(out _)?new(SelectionKind.PlanarBrepFace,1,"Planare Teilfläche",p):new(SelectionKind.BrepFace,1,"Teilfläche",p);}if(n=="BrepEdge"&&b!=null&&ci.Index>=0&&ci.Index<b.Edges.Count)return new(SelectionKind.BrepEdge,1,"Brep-Kante",b.Edges[ci.Index].GetBoundingBox(true).Center);if(o.Geometry is Mesh m){if(n.Contains("Face",StringComparison.OrdinalIgnoreCase))return new(SelectionKind.MeshFace,1,"Mesh-Fläche",a);if(n.Contains("Edge",StringComparison.OrdinalIgnoreCase))return new(SelectionKind.MeshEdge,1,"Mesh-Kante",a);if(n.Contains("Vertex",StringComparison.OrdinalIgnoreCase))return new(SelectionKind.MeshVertex,1,"Mesh-Vertex",a);}if(o.Geometry is SubD){if(n.Contains("Face",StringComparison.OrdinalIgnoreCase))return new(SelectionKind.SubDFace,1,"SubD-Fläche",a);if(n.Contains("Edge",StringComparison.OrdinalIgnoreCase))return new(SelectionKind.SubDEdge,1,"SubD-Kante",a);if(n.Contains("Vertex",StringComparison.OrdinalIgnoreCase))return new(SelectionKind.SubDVertex,1,"SubD-Vertex",a);}return Obj(o,a);}
 static BoundingBox Box(List<RhinoObject>s){var b=BoundingBox.Empty;foreach(var o in s)b.Union(o.Geometry.GetBoundingBox(true));return b;}
 static SelectionContext Obj(RhinoObject o,Point3d a){if(o is InstanceObject)return new(SelectionKind.Block,1,"Blockinstanz",a);return o.Geometry switch{Curve c when c.IsClosed&&c.IsPlanar()=>new(SelectionKind.ClosedPlanarCurve,1,"Geschlossene planare Kurve",a),Curve=>new(SelectionKind.Curve,1,"Kurve",a),Brep b when b.Faces.Count==1&&b.Faces[0].TryGetPlane(out _)=>new(SelectionKind.PlanarSurface,1,"Planare Fläche",a),Brep b when b.Faces.Count==1=>new(SelectionKind.Surface,1,"Fläche",a),Brep b when b.IsSolid=>new(SelectionKind.SolidBrep,1,"Geschlossener Körper",a),Brep=>new(SelectionKind.Brep,1,"Flächenverband",a),Extrusion e when e.IsSolid=>new(SelectionKind.SolidBrep,1,"Geschlossene Extrusion",a),Extrusion=>new(SelectionKind.Surface,1,"Extrusion",a),Mesh=>new(SelectionKind.Mesh,1,"Mesh",a),SubD=>new(SelectionKind.SubD,1,"SubD",a),_=>new(SelectionKind.Mixed,1,o.ObjectType.ToString(),a)};}
}
